<?php
namespace App\Jobs;
use App\Models\ModerationScan; use App\Models\Report; use App\Models\Role; use App\Services\Moderation\ImageModerationService; use App\Services\NotificationService; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; use Illuminate\Support\Facades\Storage;
class ModerateProductImage implements ShouldQueue { use Dispatchable,InteractsWithQueue,Queueable,SerializesModels; public int $tries=3; public function __construct(public int $scanId){} public function handle(ImageModerationService $service):void { $scan=ModerationScan::with(['product','image','store.user','store.sellerProfile'])->findOrFail($this->scanId);$scan->update(['status'=>'scanning']);try{$r=$service->scan(Storage::disk('public')->path($scan->image->path));$status=($r['status']??'clean')==='flagged'?'flagged':'clean';$scan->update(['provider'=>config('services.image_moderation.provider','local'),'provider_reference'=>$r['reference']??null,'status'=>$status,'detected_category'=>$r['category']??null,'confidence'=>$r['confidence']??null,'risk_level'=>$r['risk_level']??'low']);if($status==='flagged')$this->flag($scan);else{$unresolved=$scan->product->moderationScans()->whereIn('status',['pending_scan','scanning','flagged','under_review','scan_failed'])->exists();if($unresolved)$scan->product->update(['moderation_status'=>'pending_scan','is_active'=>false]);else{$scan->product->update(['moderation_status'=>'clean']);if($scan->store?->isMarketplaceActive()&&$scan->product->publication_status==='published')$scan->product->update(['is_active'=>true]);}}}catch(\Throwable $e){$scan->update(['status'=>'scan_failed','failure_message'=>'Moderation provider temporarily unavailable.']);$scan->product->update(['moderation_status'=>'scan_failed','is_active'=>false]);report($e);}}
private function flag(ModerationScan $scan):void{$scan->product->update(['moderation_status'=>'flagged','is_active'=>false]);$report=Report::where('target_type',get_class($scan->product))->where('target_id',$scan->product_id)->whereIn('status',['open','under_review','escalated'])->first();if($report)$report->increment('related_count');else $report=Report::create(['report_number'=>Report::number(),'target_type'=>get_class($scan->product),'target_id'=>$scan->product_id,'reason'=>'inappropriate_product_image','description'=>'Automated moderation detected possible '.str_replace('_',' ',$scan->detected_category??'policy violation').'.','priority'=>in_array($scan->risk_level,['high','critical'])?$scan->risk_level:'high','source'=>'automated_moderation']);foreach(Role::whereIn('slug',['admin','super_admin'])->with('users')->get() as $role)foreach($role->users as $user)NotificationService::send($user->id,'Product requires moderation review',"{$scan->product->name} was flagged for human review.",'moderation',$role->slug==='super_admin'?route('superadmin.moderation.show',$scan):route('admin.moderation.show',$scan));if($scan->seller_id)NotificationService::send($scan->seller_id,'Product under review','Your product is currently under review.','moderation',route('seller.products.index'));}}
